#include "IconData.hpp"

namespace google_ui::icon {

const char kButtonHtml[] = R"GOOGLEUI(
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><style>
*{box-sizing:border-box;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:transparent;touch-action:none}body{display:flex;align-items:center;justify-content:center;padding:0}#button{width:100%;height:100%;border-radius:50%;clip-path:circle(50% at 50% 50%);overflow:hidden;background:rgba(18,18,18,.94);border:3px solid rgba(224,179,81,.96);box-shadow:inset 0 0 0 2px rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;touch-action:none}#button.pressed{transform:scale(.94)}img{display:block;width:86%;height:86%;object-fit:contain;pointer-events:none}
</style></head><body><div id="button"><img alt="Google" src="data:image/png;base64,"></div><script>
(()=>{
const button=document.getElementById('button');let seq=0;
const emit=()=>{const payload='toggle:0:0:'+(++seq);document.title='CBUI:'+payload;try{history.replaceState(null,'','#'+payload);}catch(_){try{location.hash=payload;}catch(__){}}};
const press=e=>{button.classList.add('pressed');e.preventDefault();e.stopPropagation();};
const release=e=>{button.classList.remove('pressed');emit();e.preventDefault();e.stopPropagation();};
button.addEventListener('pointerdown',press,{passive:false});
button.addEventListener('pointerup',release,{passive:false});
button.addEventListener('pointercancel',e=>{button.classList.remove('pressed');e.preventDefault();e.stopPropagation();},{passive:false});
button.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();});
document.addEventListener('touchmove',e=>{e.preventDefault();e.stopPropagation();},{passive:false});
document.addEventListener('contextmenu',e=>{e.preventDefault();e.stopPropagation();});
})();
</script></body></html>
)GOOGLEUI";

} // namespace google_ui::icon
